import fs from "node:fs";

import { expect, sample, test, uniqueName } from "../../fixtures";

test("extraction completes in the background", { tag: "@DOC-02" }, async ({ apiAs }) => {
  // Arrange: a vendor in draft status
  const member = await apiAs("member");
  const vendorRes = await member.post("/api/vendors", {
    data: {
      name: uniqueName("Doc Vendor"),
      category: "services",
      contact_email: "ops@example.com",
    },
  });
  expect(vendorRes.status(), await vendorRes.text()).toBe(201);
  const vendor = await vendorRes.json();
  expect(vendor.status, await vendorRes.text()).toBe("draft");

  // Act: upload the insurance certificate sample
  const uploadRes = await member.post(`/api/vendors/${vendor.id}/documents`, {
    multipart: {
      kind: "insurance_certificate",
      file: {
        name: "insurance_certificate.txt",
        mimeType: "text/plain",
        buffer: fs.readFileSync(sample("insurance_certificate.txt")),
      },
    },
  });
  expect(uploadRes.status(), await uploadRes.text()).toBe(201);
  const document = await uploadRes.json();

  // Assert: processing finishes in the background
  await expect
    .poll(
      async () => {
        const res = await member.get(`/api/documents/${document.id}`);
        expect(res.status(), await res.text()).toBe(200);
        return (await res.json()).status;
      },
      { timeout: 30_000, message: "document should reach extracted" },
    )
    .toBe("extracted");

  const extractionRes = await member.get(`/api/documents/${document.id}/extraction`);
  expect(extractionRes.status(), await extractionRes.text()).toBe(200);
  const extraction = await extractionRes.json();

  expect(Object.keys(extraction.fields).sort(), await extractionRes.text()).toEqual(
    ["coverage_amount", "expiry_date", "insurer", "policy_number"].sort(),
  );
  for (const [name, field] of Object.entries(extraction.fields) as [
    string,
    { confidence: number },
  ][]) {
    expect(field.confidence, `confidence of ${name}`).toBeGreaterThanOrEqual(0);
    expect(field.confidence, `confidence of ${name}`).toBeLessThanOrEqual(1);
  }
});
